(()=>{const A=Abibi,page=document.body.dataset.page;let cat=new URLSearchParams(location.search).get('category')||'همه',query='',offersOnly=new URLSearchParams(location.search).get('offers')==='1';const cats=[['همه','burger.jpg'],['برگر','burger.jpg'],['پیتزا','pizza.jpg'],['صبحانه','breakfast.jpg'],['پیش‌غذا','fries.jpg']];const normalize=s=>s.replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\s‌]+/g,'');function renderDeals(){const track=A.$('#deals-carousel');if(!track)return;const position=track.scrollLeft;track.innerHTML=A.D.products.filter(p=>p.salePrice).map(p=>`<article class="deal-card"><span class="deal-percent">${A.fa(A.discount(p))}<small>٪ آف</small></span><a href="product.html?id=${p.id}"><img src="assets/image/${p.img}" alt="${p.name}" loading="lazy"></a><div class="deal-body"><a href="product.html?id=${p.id}"><h3>${p.name}</h3></a><div class="d-flex align-items-center justify-content-between gap-2">${A.pricing(p)}<button type="button" class="deal-add" data-add="${p.id}" aria-label="افزودن ${p.name}">+</button></div></div></article>`).join('');track.scrollLeft=position}
function render(){if(A.$('#categories'))A.$('#categories').innerHTML=cats.map(([c,img])=>`<a href="menu.html?category=${encodeURIComponent(c)}" class="category ${cat===c?'active':''}" data-category="${c}"><img src="assets/image/${img}" alt=""><span>${c==='همه'?'همه غذاها':c}</span></a>`).join('');if(page==='home'){A.$('#specials').innerHTML=A.D.products.filter(p=>p.special).map(p=>A.card(p,{special:true})).join('');renderDeals();A.$('#bestsellers').innerHTML=[5,6,2,7].map(i=>A.card(A.product(i))).join('')}if(page==='menu'){const list=A.D.products.filter(p=>(!offersOnly||p.salePrice)&&(cat==='همه'||cat===p.cat)&&normalize(p.name+' '+p.desc).includes(normalize(query)));A.$('#menu-results').innerHTML=list.length?list.map(p=>A.card(p,{col:'col-6 col-xl-4'})).join(''):`<div class="col-12">${A.empty('غذایی پیدا نشد','نام یا دسته‌بندی دیگری انتخاب کن.',null)}</div>`;A.$('#cart-preview').innerHTML=A.count()?A.summary():A.empty('سبدت خالیه','یک غذای خوشمزه انتخاب کن.',null)}if(page==='favorites'){const list=A.D.products.filter(p=>A.state.favorites.includes(p.id));A.$('#favorites-list').innerHTML=list.length?list.map(p=>A.card(p,{col:'col-6 col-xl-4'})).join(''):`<div class="col-12 surface">${A.empty('هنوز علاقه‌مندی نداری','با لمس قلب کنار غذاها، انتخاب‌هایت را ذخیره کن.')}</div>`}}
if(page==='product'){const p=A.product(new URLSearchParams(location.search).get('id'));A.$('#product-detail').innerHTML=p?`<div class="row g-4 align-items-center"><div class="col-md-6"><img class="product-detail-image" src="assets/image/${p.img}" alt="${p.name}"></div><div class="col-md-6 product-details"><span class="badge text-bg-light">${p.cat}</span><h2 class="my-3">${p.name}</h2><p>${p.desc}</p>${A.pricing(p)}<hr class="my-4"><form id="product-form"><div class="form-check mb-3"><input class="form-check-input" type="checkbox" id="cheese"><label class="form-check-label" for="cheese">پنیر اضافه · ۴۵٬۰۰۰ تومان (نمونه)</label></div><label class="form-label" for="food-note">توضیحات این غذا</label><input id="food-note" class="form-control mb-3" maxlength="200" placeholder="مثلاً بدون پیاز"><div id="product-total" class="mb-3">${A.money(A.unit(p))}</div><button class="btn btn-primary w-100" type="submit">افزودن به سبد</button></form><a href="menu.html" class="d-inline-block mt-3">بازگشت به منو ←</a></div></div>`:A.empty('غذا پیدا نشد','از منو یک غذا انتخاب کن.');if(p){A.$('#cheese').addEventListener('change',()=>A.$('#product-total').innerHTML=A.money(A.unit(p)+(A.$('#cheese').checked?45000:0)));A.$('#product-form').addEventListener('abibi:valid-submit',e=>{e.preventDefault();A.add(p.id,A.$('#cheese').checked?45000:0,A.$('#food-note').value.trim())})}}else render();document.addEventListener('abibi:change',()=>{if(page!=='product')render()});A.$('#food-search')?.addEventListener('input',e=>{query=e.target.value;render()});document.addEventListener('click',e=>{const c=e.target.closest('[data-category]');if(c&&page==='menu'){e.preventDefault();cat=c.dataset.category;offersOnly=false;history.replaceState(null,'','menu.html?category='+encodeURIComponent(cat));render()}});const track=A.$('#deals-carousel');if(track){const move=direction=>track.scrollBy({left:direction*(track.querySelector('.deal-card').offsetWidth+16),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});A.$('[data-deals-prev]').addEventListener('click',()=>move(1));A.$('[data-deals-next]').addEventListener('click',()=>move(-1));track.addEventListener('keydown',e=>{if(e.target!==track)return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}})}const el=A.$('#foodCarousel');if(el){const carousel=bootstrap.Carousel.getOrCreateInstance(el,{interval:6000});let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;const btn=A.$('#carousel-pause');function update(){paused?carousel.pause():carousel.cycle();btn.textContent=paused?'▶':'Ⅱ';btn.setAttribute('aria-label',paused?'ادامه اسلایدر':'توقف اسلایدر')}update();btn.addEventListener('click',()=>{paused=!paused;update()})}})();
